TLM.f("Sancti/05-12",{"officium":"Ss. Nerei, Achillei et Domitillæ Virginis atque Pancratii Martyrum","rule":["Evangelium non appropriatum","Gloria"],"fallback":"Commune/C3","from":{"Tractus":"Commune/C3"},"sections":{"Introitus":[{"k":"ref","la":"Ps 32:18; 32:19; 32:20"},{"k":"text","la":"Ecce, óculi Dómini super timéntes eum, sperántes in misericórdia ejus, allelúja: ut erípiat a morte ánimas eórum: quóniam adjútor et protéctor noster est, allelúja, allelúja."},{"k":"ref","la":"Ps 32:1"},{"k":"text","la":"Exsultáte, justi, in Dómino: rectos decet collaudátio."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Ecce, óculi Dómini super timéntes eum, sperántes in misericórdia ejus, allelúja: ut erípiat a morte ánimas eórum: quóniam adjútor et protéctor noster est, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Semper nos, Dómine, Mártyrum tuórum Nérei, Achíllei, Domitíllæ atque Pancrátii fóveat, quǽsumus, beáta solémnitas: et tuo dignos reddat obséquio."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 5:1-5"},{"k":"text","la":"Stabunt justi in magna constántia advérsus eos, qui se angustiavérunt et qui abstulérunt labóres eórum. Vidéntes turbabúntur timore horríbili, et mirabúntur in subitatióne insperátæ salútis, dicéntes intra se, pœniténtiam agéntes, et præ angústia spíritus geméntes: Hi sunt, quos habúimus aliquándo in derísum et in similitúdinem impropérii. Nos insensáti vitam illórum æstimabámus insániam, et finem illórum sine honóre: ecce, quómodo computáti sunt inter fílios Dei, et inter Sanctos sors illórum est."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Hæc est vera fratérnitas, quæ vicit mundi crímina: Christum secúta est, ínclita tenens regna cœléstia. Allelúja.","mark":"V"},{"k":"text","la":"Te Mártyrum candidátus laudat exércitus, Dómine. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Exod 15:11"},{"k":"text","la":"Gloriósus Deus in Sanctis suis: mirábilis in majestáte, fáciens prodígia."},{"k":"ref","la":"Exod 15:6"},{"k":"text","la":"Déxtera tua, Dómine, glorificáta est in virtúte: déxtera manus tua confrégit inimícos.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 4:46-53"},{"k":"text","la":"In illo témpore: Erat quidam régulus, cujus fílius infirmabátur Caphárnaum. Hic cum audísset, quia Jesus adveníret a Judǽa in Galilǽam, ábiit ad eum, et rogábat eum, ut descénderet et sanáret fílium ejus: incipiébat enim mori. Dixit ergo Jesus ad eum: Nisi signa et prodígia vidéritis, non créditis. Dicit ad eum régulus: Dómine, descénde, priúsquam moriátur fílius meus. Dicit ei Jesus: Vade, fílius tuus vivit. Crédidit homo sermóni, quem dixit ei Jesus, et ibat. Jam autem eo descendénte, servi occurrérunt ei et nuntiavérunt, dicéntes, quia fílius ejus víveret. Interrogábat ergo horam ab eis, in qua mélius habúerit. Et dixérunt ei: Quia heri hora séptima relíquit eum febris. Cognóvit ergo pater, quia illa hora erat, in qua dixit ei Jesus: Fílius tuus vivit: et crédidit ipse et domus ejus tota."}],"Offertorium":[{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: et veritátem tuam in ecclésia sanctórum(, allelúja, allelúja)."}],"Secreta":[{"k":"text","la":"Sanctórum Martyrum tuórum, quǽsumus. Dómine, Nérei, Achíllei, Domitíllæ atque Pancrátii sit tibi grata conféssio: quæ et múnera nostra comméndet, et tuam nobis indulgéntiam semper implóret."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 32:1"},{"k":"text","la":"Gaudéte, justi, in Dómino, allelúja: rectos decet collaudátio, allelúja."}],"Postcommunio":[{"k":"text","la":"Quǽsumus, Dómine: ut beatórum Mártyrum tuórum Nérei, Achíllei, Domitíllæ atque Pancrátii deprecatiónibus, sacraménta sancta, quæ súmpsimus, ad tuæ nobis profíciant placatiónis augméntum."},{"k":"macro","name":"Per Dominum"}]},"hr":{"849e490f5758e74b":{"t":"Ps 32, 18 i 19 i 20, Ps 32, 1\n(Ps 32, 18 i 19 i 20) Gle, oči Gospodnje gledaju one koji ga se boje, one koji se uzdaju u milosrđe njegovo, <i>aleluja</i>.\nOn izbavlja njihov život od smrti. On je naš pomoćnik i zaštitnik, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 32 1) Radujte se, pravednici, u Gospodinu, pravednima dolikuje da ga hvale.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 32, 18 i 19 i 20) Gle, oči Gospodnje gledaju one koji ga se boje, one koji se uzdaju u milosrđe njegovo, <i>aleluja</i>.\nOn izbavlja njihov život od smrti. On je naš pomoćnik i zaštitnik, <i>aleluja</i>, <i>aleluja</i>.","kn":"(P,s. 32, 18-20). Gle, oko je Gospodnje na onima, koji ga štuju, na onima,, koji čekaju milosrđe njegovo, aleluja; on će dušu njihovu izbaviti od smrti, jer on je pomoć naša i zaštita naša, aleluja, aleluja. (Ps. 32, 1) Radujte se, pravednici, u Gospodinu, pravedne dolikuje hvala!. Slava Ocu... Gle . . .","knRef":"Kniewald 1942, str. 572–573 (snimka 287) (OCR)"},"e62ee888c88232b7":{"t":"<i>Pomolimo se</i>.\nNeka nas uvijek potpomaže, molimo, Gospodine, blažena svetkovina mučenika tvojih Nereja, Ahileja, Domitile i Pankracija i učini dostojnima tvoje službe.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Neka nas uvijek. Gospodine, molimo, krijepi svetkovina mučenika Tvojih Nereja, Ahileja, Domitile i Pankracija i neka nas učini dostojnima Tvoje službe, po G. n.","knRef":"Kniewald 1942, str. 572–573 (snimka 287) (OCR)"},"c600ca35b26cf613":{"t":"Mudr 5, 1-5\nČitanje knjige Mudrosti. Pravednici će se junački održati protiv onih koji su ih tlačili i oteli plodove njihova truda. Kad ih bezbožnici vide, smest će se od užasnog straha i čudit će se neočekivanom njihovu spasu. Mislit će u sebi očajni i jecajući od duševne boli: To su oni kojima smo se mi nekada rugali i koje smo grdili. Mi lude! Držali smo njihov život ludošću i njihov svršetak nečasnim. A evo, kako su pribrojeni djeci Božjoj i njihova je baština među svetima.","kn":"Čitanje knjige mudrosti (5, 1-5). Pravednici će se junački održati protiv -onih, koji su ih tlačili i oteli plodove njihova truda. Kad ih bezbožnici vide, smesti će se od užasnog straha 1 čudit će se neočekivanom njihovu spasu. Mislit će u sebi raskajani i jecajući od duševne boli: To su oni, kojima smo se mi nekada rugali i koje smo grdili. Mi lude! Držali smo njihov život ludošću i njihov svršetak nečasnim. A evo, kako su pribrojeni djeci Božjoj i njihova je baština među svetima.","knRef":"Kniewald 1942, str. 568–569 (snimka 285) (OCR)"},"91f190df4dbe29b5":{"t":"<i>Aleluja</i>, <i>aleluja</i>.\nOvo je pravo bratstvo koje je pobijedilo opačine svijeta, slijedilo je Krista i zadobilo slavno nebesko kraljevstvo. <i>Aleluja</i>.\nTebe. Gospodine, hvali mučenika svijetla vojska. <i>Aleluja</i>.","kn":"Aleluja, aleluja. To je pravo bratstvo, koje je pobijedilo opačine svijeta, slijedeći Krista, zadobilo je kraljevstvo nebesko, aleluja","knRef":"Kniewald 1942, str. 590–591 (snimka 296) (OCR)"},"2cb888720d7cc4b1":{"t":"Iv 4, 46-53\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme bolovao je u Kafarnaumu sin nekoga kraljevskog činovnika. Kad je ovaj čuo, da je Isus došao iz Judeje u Galileju, pođe k njemu i zamoli ga da dođe i da mu ozdravi sina koji bijaše na umoru. Isus mu reče: Ako ne vidite znakova i čudesa, ne vjerujete. Kraljevski činovnik ponovi: Gospodine, dođi prije nego umre moj sin! Isus mu reče: Pođi! tvoj sin živi. Čovjek povjerova Isusovoj riječi i pođe. Kad se on vraćao kući dođu mu u susret sluge koji mu jave: Sin je tvoj ozdravio. On ih upita za vrijeme, kad mu je bilo bolje. Sluge mu odgovore: Jučer oko sedam sati pusti ga groznica. Tad otac upozna, da je to bilo u onaj sat kad mu Isus reče: Tvoj sin živi. I povjerova on i sav njegov dom.","kn":"t Slijedi sveto evanđelje po Ivanu (4, 46-53). U ono je . vrijeme bio neki kraljevski činovnik, čiji je sin bo'lovao u Kafarnauniu. ICad je ovaj dočuo; da je Isus došao iz Judeje u Galileju, pođe k njemu 1 zamoli ža, da sade i izliječi mu sina, koji je na umoru. Tada mu Isus reče: Ne vjerujete, ako ne vidite znakova i čudesa. Reče mu kraljevski činovnik: .Gospodine, siđi prije nego .nii umre sin. Isus mu reče: Idi, tvoj sin živi! I povjerova čovjek Isusovoj riječi 1 pođe. A kad je on već silazio, sretnu ga sluge i jave mu, da mu sin živi. On ih upita za uru, kad mu je krenulo na bolje. Odgovore: Pustila ga je groznica jučer u sedmoj uri. Tada upozna otac, da je to bila ona ura, kad mu je Isus rekao: Sin tvoj živi! I povjerova on i sva njegova kuća.. . ' '","knRef":"Kniewald 1942, str. 424–425 (snimka 213) (OCR)"},"f6559b160ccd64cf":{"t":"Ps 88, 6\nNebesa slave tvoja čudesa, Gospodine, a zbor svetih tvoju vjernost, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Ps. 88, 6). Nebesa slave čudesa Tvoja, Gospodine, i Tvoju vjernost sveti puk Tvoj, aleluja, aleluja.","knRef":"Kniewald 1942, str. 558–559 (snimka 280) (OCR)"},"e1874c46ab8b71f6":{"t":"Bilo ti milo, molimo Gospodine, priznavanje svetih mučenika tvojih Nereja, Ahileja, Domitile i Pankracija. da preporuči naše darove i uvijek nam isprosi tvoje oproštenje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, bila Ti draga ispovijed mučenika Tvojih Nereja, Ahileja, Domitile i Pankracija, te preporučila Tebi naše darove i isprosila nam uvijek Tvoje oproštenje, po G. n.","knRef":"Kniewald 1942, str. 572–573 (snimka 287) (OCR)"},"1a0a565aa39e4fe3":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>u ovo</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"j Uistinu je dostojno i pravedno, pravo i spaso- I doba, ali osobito svečano na - današnji dan, (u ovo vrijeme), kad je žrtvovano naše vazmeno Janje, I Isukrst; jer On je pravo janje, koje je uzelo grijehe : svojim je uskrsnućem obnovio naš ž^vot. Zato pje- I vamo pjesmu Tvoje slave s anđelima i s arkanđe lima, s. prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"aa30249bc0fea185":{"t":"Ps 32, 1\nRadujte se, pravednici u Gospodinu, <i>aleluja</i>,\npravednima dolikuje da ga hvale, <i>aleluja</i>.","kn":"(Ps. 32, 1). Radujte se, pravednici, u Gospodinu, pravedne dolikuje hvala, aleluja.","knRef":"Kniewald 1942, str. 572–573 (snimka 287) (OCR)"},"f9cb46e6b06deb17":{"t":"<i>Pomolimo se</i>.\nMolimo, Gospodine, da nam po molitvama blaženih mučenika tvojih Nereja, Ahileja, Domitile i Pankracija sveta otajstva koja smo primili povećaju pomirenje s tobom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"e3481c16f40c8803":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – On se poslije svojeg uskrsnuća svim svojim učenicima javno ukazao i pred njihovim se očima uzdigao na nebo, da nas učini dionicima svoga božanstva. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vječni Bože, jer je otajstvom utjelovljene Riječi očima naše duše zasjalo novo svijetlo Tvoje sjajnosti, te nas Bog, dok ga spoznajemo u vidljivom obličju, privlači da ljubimo i nevidljive stvari. I zato pjevamo pjesmu slave Tvoje s anđelima i arkanđelima, s prijestolima 1 s gospodstvima, sa svom silom nebeske vojske govoreći bez prestanka: Korizmeno predslovlje.","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"}}});
